            <table class="invoice-table"><thead><tr><th>Bill No</th><th>Date</th><th>SO No</th><th>LR No</th><th>Trips</th><th class="amount">Total</th><th class="amount">Paid</th><th class="amount">Outstanding</th><th>Attachments</th><th>Edit</th><th>Print</th></tr></thead><tbody id="invoiceBody"><tr><td colspan="11" class="empty-area">Select a customer to see bills.</td></tr></tbody></table>
