@push('scripts')
<script>
document.addEventListener('DOMContentLoaded',()=>{
    const csrf=document.querySelector('meta[name="csrf-token"]').content;
    const routes={data:@json(route('sale.billing.data')),soOptions:@json(route('sale.billing.so-options')),store:@json(route('sale.billing.store')),base:@json(url('/sale/bills'))};
    const customerBtn=document.getElementById('customerBtn'),soBtn=document.getElementById('soBtn'),tripBody=document.getElementById('tripBody'),invoiceBody=document.getElementById('invoiceBody'),tripWrap=document.getElementById('tripWrap');
    const footerStatus=document.getElementById('footerStatus'),headerStatus=document.getElementById('headerStatus'),checkAllBtn=document.getElementById('checkAllBtn'),createBillBtn=document.getElementById('createBillBtn'),cancelEditBtn=document.getElementById('cancelEditBtn'),attachmentPicker=document.getElementById('lrAttachmentPicker');
    const initialParams=new URL(window.location.href).searchParams;
    const initialEditId=Number(initialParams.get('edit_invoice_id'))||null;
    let initialVoucherId=Number(initialParams.get('voucher_id'))||null;
    let shortcutSelectionApplied=false;
    let state={customerId:Number(customerBtn.dataset.customerId)||null,customerName:customerBtn.textContent.trim(),soId:Number(soBtn.dataset.soId)||null,order:null,trips:[],invoices:[],selected:new Set(),tripOpener:null,editOpener:null,editReturn:null,printOpener:null,editingInvoiceId:initialEditId,editingInvoice:null,pendingFiles:new Map(),removedAttachmentIds:new Set(),attachmentVoucherId:null};
    const money=n=>'₹'+Number(n||0).toLocaleString('en-IN',{minimumFractionDigits:2,maximumFractionDigits:2});
    const esc=s=>String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
    const today=()=>{const d=new Date(),o=d.getTimezoneOffset();return new Date(d.getTime()-o*60000).toISOString().slice(0,10)};
    async function responseData(response,fallback){const type=response.headers.get('content-type')||'';if(!type.includes('application/json'))throw new Error(fallback);return response.json();}
    const setStatus=(msg,type='')=>{footerStatus.textContent=msg;footerStatus.className='status '+type;headerStatus.textContent=msg;headerStatus.className='text-[11px] font-black '+(type==='error'?'text-red-700':'text-emerald-700')};
    function syncButtons(){const edit=!!state.editingInvoiceId;checkAllBtn.disabled=edit;cancelEditBtn.classList.toggle('hidden',!edit);createBillBtn.innerHTML=edit?'Edit Bill <span class="kbd">Ctrl+B</span>':'Create Bill <span class="kbd">Ctrl+B</span>';}
    const updateUrl=()=>{const u=new URL(window.location.href);state.customerId?u.searchParams.set('customer_id',state.customerId):u.searchParams.delete('customer_id');state.soId?u.searchParams.set('sales_order_id',state.soId):u.searchParams.delete('sales_order_id');state.editingInvoiceId?u.searchParams.set('edit_invoice_id',state.editingInvoiceId):u.searchParams.delete('edit_invoice_id');history.replaceState({},'',u.pathname+u.search)};
    function clearAttachmentDraft(){state.pendingFiles.forEach(files=>files.forEach(item=>URL.revokeObjectURL(item.url)));state.pendingFiles=new Map();state.removedAttachmentIds=new Set();state.attachmentVoucherId=null;attachmentPicker.value='';}
    function clearEdit(){state.editingInvoiceId=null;state.editingInvoice=null;state.editOpener=null;state.editReturn=null;clearAttachmentDraft();syncButtons();}

    function openCustomer(search=''){
        window.MasterSelector.open({type:'customers',title:'Select Customer',search,opener:customerBtn,onSelect:item=>{clearEdit();state.customerId=Number(item.id);state.customerName=item.name;state.soId=null;state.order=null;state.selected.clear();customerBtn.dataset.customerId=item.id;customerBtn.textContent=item.name;customerBtn.classList.remove('empty');soBtn.dataset.soId='';soBtn.textContent='Select SO';soBtn.classList.add('empty');soBtn.disabled=false;updateUrl();loadData(false).then(()=>setTimeout(()=>soBtn.focus(),20));}});
    }
    function openSO(search=''){
        if(!state.customerId){setStatus('Select Customer first.','error');window.AppToast?.('Select Customer first.','error');customerBtn.focus();return;}
        const url=routes.soOptions+'?customer_id='+encodeURIComponent(state.customerId);
        window.MasterSelector.open({url,title:'Select Pending SO',search,opener:soBtn,onSelect:item=>{clearEdit();state.soId=Number(item.id);state.selected.clear();soBtn.dataset.soId=item.id;soBtn.textContent=item.so_number||item.name;soBtn.classList.remove('empty');updateUrl();loadData(true);}});
    }
    customerBtn.addEventListener('click',()=>openCustomer());soBtn.addEventListener('click',()=>openSO());
    [customerBtn,soBtn].forEach(btn=>btn.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();btn===customerBtn?openCustomer():openSO();}else if(e.key==='Backspace'){e.preventDefault();clearEdit();if(btn===customerBtn){state.customerId=null;state.customerName='';state.soId=null;customerBtn.textContent='Select Customer';customerBtn.classList.add('empty');soBtn.textContent='Select SO';soBtn.classList.add('empty');soBtn.disabled=true;}else{state.soId=null;soBtn.textContent='Select SO';soBtn.classList.add('empty');}state.selected.clear();updateUrl();loadData(false);}}));

    async function loadData(focusTrips=false){
        const u=new URL(routes.data,window.location.origin);if(state.customerId)u.searchParams.set('customer_id',state.customerId);if(state.soId)u.searchParams.set('sales_order_id',state.soId);if(state.editingInvoiceId)u.searchParams.set('edit_invoice_id',state.editingInvoiceId);
        try{setStatus('Loading...');const r=await fetch(u,{headers:{Accept:'application/json'}}),d=await responseData(r,'Unable to load billing data.');if(!r.ok)throw new Error(d.message||'Unable to load billing data');
            if(d.customer){state.customerId=Number(d.customer.id);state.customerName=d.customer.name;customerBtn.dataset.customerId=d.customer.id;customerBtn.textContent=d.customer.name;customerBtn.classList.remove('empty');soBtn.disabled=false;}
            state.order=d.order;state.trips=d.trips||[];state.invoices=d.invoices||[];state.editingInvoice=d.editing_invoice||null;if(state.order){state.soId=Number(state.order.id);soBtn.dataset.soId=state.order.id;soBtn.textContent=state.order.so_number;soBtn.classList.remove('empty');}
            state.selected=new Set([...state.selected].filter(id=>state.trips.some(t=>t.id===id&&!t.billed)));
            let shortcutVoucher=null;
            if(!state.editingInvoiceId&&initialVoucherId){
                shortcutVoucher=state.trips.find(t=>Number(t.id)===Number(initialVoucherId))||null;
                if(shortcutVoucher&&!shortcutVoucher.billed){
                    state.selected.add(Number(shortcutVoucher.id));
                    shortcutSelectionApplied=true;
                }else if(shortcutVoucher?.billed){
                    window.AppToast?.(`LR ${shortcutVoucher.lr_no||shortcutVoucher.sr_no} is already billed.`,'warning',4500);
                }
                initialVoucherId=null;
                const cleanUrl=new URL(window.location.href);
                cleanUrl.searchParams.delete('voucher_id');
                history.replaceState({},'',cleanUrl.pathname+cleanUrl.search);
            }
            renderAll();syncButtons();updateUrl();setStatus(state.editingInvoice?`Editing ${state.editingInvoice.bill_no} · ${state.trips.length} trip(s) loaded`:state.order?`${state.order.pending_count} truck(s) pending billing`:'Ready','ok');
            if(shortcutSelectionApplied&&shortcutVoucher){
                setTimeout(()=>{const c=tripBody.querySelector(`[data-trip-check="${shortcutVoucher.id}"]`);const row=tripBody.querySelector(`[data-voucher-row="${shortcutVoucher.id}"]`);row?.scrollIntoView({block:'center',inline:'nearest'});c?.focus();},30);
            }else if(focusTrips)setTimeout(()=>focusFirstPending(),20);
            return true;
        }catch(err){setStatus(err.message||'Unable to load','error');window.AppToast?.(err.message||'Unable to load billing data.','error');return false;}
    }
    function renderAll(){renderSummary();renderTrips();renderInvoices();updateSelectionStatus();}
    function renderSummary(){const box=document.getElementById('soSummary');if(!state.order){box.classList.add('hidden');return;}box.classList.remove('hidden');document.getElementById('sumSo').textContent=state.order.so_number;document.getElementById('sumRoute').textContent=`${state.order.from_location} → ${state.order.to_location}`;document.getElementById('sumDescription').textContent=state.order.description||'-';document.getElementById('sumRate').textContent=money(state.order.per_trip_cost);document.getElementById('sumTrips').textContent=`${state.order.billed_count} billed / ${state.order.voucher_count} sent / ${state.order.trips_quantity} ordered`;document.getElementById('sumPending').textContent=state.order.pending_count;}
    function savedAttachments(trip){return (trip.attachments||[]).filter(item=>!state.removedAttachmentIds.has(Number(item.id)));}
    function pendingAttachments(voucherId){return state.pendingFiles.get(Number(voucherId))||[];}
    function attachmentMarkup(trip,editing){const saved=savedAttachments(trip).map(item=>{const image=(item.mime_type||'').startsWith('image/');return `<span class="lr-attachment">${image?`<img src="${item.url}" alt="">`:'<b>PDF</b>'}<a class="lr-attachment-name text-blue-700 underline" href="${item.url}" target="_blank" rel="noopener" title="${esc(item.name)}">${esc(item.name)}</a>${editing?`<button type="button" class="lr-attachment-remove" data-remove-saved="${item.id}" data-voucher-id="${trip.id}" aria-label="Remove ${esc(item.name)}">×</button>`:''}</span>`;}).join('');const pending=pendingAttachments(trip.id).map((item,index)=>`<span class="lr-attachment pending-file">${item.file.type.startsWith('image/')?`<img src="${item.url}" alt="">`:'<b>PDF</b>'}<span class="lr-attachment-name" title="${esc(item.file.name)}">${esc(item.file.name)}</span><button type="button" class="lr-attachment-remove" data-remove-pending="${index}" data-voucher-id="${trip.id}" aria-label="Remove ${esc(item.file.name)}">×</button></span>`).join('');const canAdd=editing||!trip.billed;return `<div class="lr-attachments">${saved}${pending}${canAdd?`<button type="button" class="lr-add" data-add-attachment="${trip.id}">+ Add Attachment</button>`:''}</div>`;}
    function renderTrips(){if(!state.order){tripBody.innerHTML='<tr><td colspan="12" class="empty-area">Select Customer and pending SO.</td></tr>';return;}if(!state.trips.length){tripBody.innerHTML='<tr><td colspan="12" class="empty-area">No voucher/truck entries found.</td></tr>';return;}const editing=!!state.editingInvoiceId;tripBody.innerHTML=state.trips.map((t,i)=>`<tr class="${editing?'editing-bill':(t.billed?'billed':'pending')}" data-trip-row="${i}" data-voucher-row="${t.id}"><td class="text-center">${editing||t.billed?'<span class="status-badge">✓</span>':`<input type="checkbox" class="trip-check" data-trip-check="${t.id}" data-trip-index="${i}" ${state.selected.has(t.id)?'checked':''}>`}</td><td class="status-cell"><span class="status-badge">${editing?'IN BILL':(t.billed?'BILLED':'PENDING')}</span></td><td>${esc(t.sr_no)}</td><td>${esc(t.lr_no||'-')}</td><td>${esc(t.lr_date||'-')}</td><td>${esc(t.lorry_number||'-')}</td><td>${esc(t.vehicle_type||'-')}</td><td>${esc(t.company_name||'-')}</td><td>${esc(t.supplier||'-')}</td><td>${t.billed?`<button type="button" class="action-link" data-print-invoice="${t.invoice_id}">${esc(t.bill_no)}</button>`:'-'}</td><td>${attachmentMarkup(t,editing)}</td><td>${esc(t.description||'-')}</td></tr>`).join('');}
    function invoiceLrMarkup(invoice){
        const lrNumbers=String(invoice.lr_numbers_text||'').split(',').map(v=>v.trim()).filter(Boolean);
        if(!lrNumbers.length)return '-';
        const attachments=invoice.attachments||[];
        return lrNumbers.map(lr=>{
            const needle=lr.toLowerCase();
            const attachment=attachments.find(a=>{
                const attachmentLr=String(a.lr_no||a.voucher_lr_no||a.lr_number||'').trim().toLowerCase();
                if(attachmentLr&&attachmentLr===needle)return true;
                const name=String(a.name||a.original_name||'').trim().toLowerCase();
                return name===needle||name.startsWith(needle+' -')||name.startsWith(needle+'_')||name.startsWith(needle+' ');
            });
            return attachment?.url
                ? `<a href="${esc(attachment.url)}" target="_blank" rel="noopener" class="action-link" title="Open attachment for LR ${esc(lr)}">${esc(lr)}</a>`
                : esc(lr);
        }).join(', ');
    }
    function renderInvoices(){if(!state.customerId){invoiceBody.innerHTML='<tr><td colspan="11" class="empty-area">Select a customer to see bills.</td></tr>';return;}if(!state.invoices.length){invoiceBody.innerHTML='<tr><td colspan="11" class="empty-area">No bills generated for this selection.</td></tr>';return;}invoiceBody.innerHTML=state.invoices.map(i=>`<tr><td><b>${esc(i.bill_no)}</b></td><td>${esc(i.invoice_date)}</td><td>${esc(i.so_number||'-')}</td><td>${invoiceLrMarkup(i)}</td><td>${i.trip_count}</td><td class="amount"><b>${money(i.total_amount)}</b></td><td class="amount">${money(i.paid_amount)}</td><td class="amount" style="color:${i.outstanding>0?'#b91c1c':'#047857'}"><b>${money(i.outstanding)}</b></td><td class="attachment-list">${i.attachments?.length?i.attachments.map(a=>`<a href="${a.url}" target="_blank" rel="noopener">${esc(a.name)}</a>`).join(''):'-'}</td><td><button type="button" class="action-link" data-edit-invoice="${i.id}">Edit</button></td><td><button type="button" class="action-link" data-print-invoice="${i.id}">Print</button></td></tr>`).join('');}
    function pendingChecks(){return Array.from(document.querySelectorAll('[data-trip-check]'));}
    function focusFirstPending(){pendingChecks()[0]?.focus();}
    function focusCheckByPosition(current,delta){const arr=pendingChecks();const i=arr.indexOf(current);arr[Math.max(0,Math.min(arr.length-1,i+delta))]?.focus();}
    tripBody.addEventListener('change',e=>{const c=e.target.closest('[data-trip-check]');if(!c)return;const id=Number(c.dataset.tripCheck);c.checked?state.selected.add(id):state.selected.delete(id);updateSelectionStatus();});
    tripBody.addEventListener('keydown',e=>{const c=e.target.closest('[data-trip-check]');if(!c)return;if(e.key==='Enter'){e.preventDefault();c.checked=!c.checked;c.dispatchEvent(new Event('change',{bubbles:true}));focusCheckByPosition(c,1);}else if(e.key==='ArrowDown'){e.preventDefault();focusCheckByPosition(c,1);}else if(e.key==='ArrowUp'){e.preventDefault();focusCheckByPosition(c,-1);}});
    tripBody.addEventListener('click',e=>{const add=e.target.closest('[data-add-attachment]');if(add){state.attachmentVoucherId=Number(add.dataset.addAttachment);attachmentPicker.value='';attachmentPicker.click();return;}const removePending=e.target.closest('[data-remove-pending]');if(removePending){const voucherId=Number(removePending.dataset.voucherId),files=pendingAttachments(voucherId),index=Number(removePending.dataset.removePending);if(files[index])URL.revokeObjectURL(files[index].url);files.splice(index,1);state.pendingFiles.set(voucherId,files);renderTrips();setTimeout(()=>tripBody.querySelector(`[data-add-attachment="${voucherId}"]`)?.focus(),0);return;}const removeSaved=e.target.closest('[data-remove-saved]');if(removeSaved&&state.editingInvoiceId){state.removedAttachmentIds.add(Number(removeSaved.dataset.removeSaved));const voucherId=Number(removeSaved.dataset.voucherId);renderTrips();setTimeout(()=>tripBody.querySelector(`[data-add-attachment="${voucherId}"]`)?.focus(),0);return;}const p=e.target.closest('[data-print-invoice]');if(p)openPrint(Number(p.dataset.printInvoice),p,true);});
    attachmentPicker.addEventListener('change',()=>{const selected=Array.from(attachmentPicker.files||[]),voucherId=state.attachmentVoucherId;if(!selected.length||!voucherId)return;const allowed=['application/pdf','image/jpeg','image/png','image/webp'],files=pendingAttachments(voucherId),savedCount=savedAttachments(state.trips.find(t=>Number(t.id)===voucherId)||{}).length;let rejected=false;for(const file of selected){if(!allowed.includes(file.type)){window.AppToast?.(`${file.name}: only PDF, JPG, PNG or WEBP files are allowed.`,'error');rejected=true;continue;}if(file.size>10*1024*1024){window.AppToast?.(`${file.name}: attachment must not exceed 10 MB.`,'error');rejected=true;continue;}if(savedCount+files.length>=20){window.AppToast?.('A maximum of 20 attachments is allowed per LR.','warning');rejected=true;break;}files.push({file,url:URL.createObjectURL(file)});}state.pendingFiles.set(voucherId,files);renderTrips();if(!rejected||files.length)setTimeout(()=>tripBody.querySelector(`[data-add-attachment="${voucherId}"]`)?.focus(),0);});
    function selectedTrips(){return state.trips.filter(t=>state.selected.has(Number(t.id)));}
    function selectedDefaultFreight(){return selectedTrips().length*Number(state.order?.per_trip_cost||0);}
    function selectedOtherCharges(){return selectedTrips().reduce((sum,t)=>sum+Number(t.other_charges||0),0);}
    function taxMode(){const mode=state.editingInvoice?.tax_mode||state.order?.tax_mode;return ['rcm','hiring','gst','na'].includes(mode)?mode:'rcm';}
    function invoiceMath(freight,other){const mode=taxMode(),rate=mode==='hiring'?18:(mode==='gst'?Number(state.editingInvoice?.gst_rate??state.order?.gst_rate??0):0),gst=freight*rate/100,rcm=mode==='rcm'?freight*.05:0;return{mode,rate,gst,rcm,total:freight+gst+other};}
    function updateSelectionStatus(){if(state.editingInvoice){footerStatus.textContent=`Editing ${state.editingInvoice.bill_no} · ${state.trips.length} trip(s)`;return;}const c=state.selected.size,freight=selectedDefaultFreight(),other=selectedOtherCharges(),math=invoiceMath(freight,other);footerStatus.textContent=c?`${c} truck(s) selected · Freight ${money(freight)} · Total ${money(math.total)}`:'No trucks selected';}
    function toggleAll(){if(!state.order||state.editingInvoiceId)return;const pending=state.trips.filter(t=>!t.billed).map(t=>t.id);const all=pending.length&&pending.every(id=>state.selected.has(id));state.selected=new Set(all?[]:pending);renderTrips();updateSelectionStatus();if(!all)focusFirstPending();}
    checkAllBtn.addEventListener('click',toggleAll);

    const billModal=document.getElementById('billModal'),billForm=document.getElementById('billForm'),invoiceDate=document.getElementById('invoiceDate'),totalInput=document.getElementById('billTotalAmount'),remarksInput=document.getElementById('billRemarks'),billSubmit=document.getElementById('billSubmit');
    function updateDraft(){const editing=!!state.editingInvoiceId,freight=Number(totalInput.value||0),other=editing?Number(state.editingInvoice?.other_charges||0):selectedOtherCharges(),math=invoiceMath(freight,other),count=state.editingInvoice?Number(state.editingInvoice.trip_count||state.trips.length):state.selected.size;document.getElementById('draftTrips').textContent=count;document.getElementById('draftTaxMode').textContent=math.mode.toUpperCase();document.getElementById('draftFreight').textContent=money(freight);document.getElementById('draftGst').textContent=money(math.gst);document.getElementById('draftOther').textContent=money(other);document.getElementById('draftTotal').textContent=money(math.total);document.getElementById('draftRcm').textContent=money(math.rcm);document.getElementById('draftRcmNote').classList.toggle('hidden',math.mode!=='rcm');}
    function openBill(){const editing=!!state.editingInvoiceId;if(!state.customerId||!state.soId){window.AppToast?.('Select Customer and SO first.','error');return;}if(!editing&&!state.selected.size){window.AppToast?.('Select at least one acknowledged truck.','error');focusFirstPending();return;}if(editing&&!state.editingInvoice){window.AppToast?.('Bill details are still loading.','warning');return;}state.tripOpener=document.activeElement;invoiceDate.value=editing?(state.editingInvoice.invoice_date_raw||today()):today();totalInput.value=editing?Number(state.editingInvoice.customer_freight||0).toFixed(2):selectedDefaultFreight().toFixed(2);remarksInput.value=editing?(state.editingInvoice.remarks||''):'';document.getElementById('billModalTitle').textContent=editing?`Edit ${state.editingInvoice.bill_no}`:'Create Invoice from Acknowledged Trucks';billSubmit.innerHTML=editing?'Save Changes & Print <span class="kbd">Ctrl+S</span>':'Create Bill & Print <span class="kbd">Ctrl+S</span>';updateDraft();billModal.classList.remove('hidden');setTimeout(()=>invoiceDate.focus(),20);}
    function closeBill(){billModal.classList.add('hidden');const target=state.tripOpener?.isConnected?state.tripOpener:createBillBtn;setTimeout(()=>target.focus(),0);}
    function requiredVoucherIds(){return state.editingInvoiceId?state.trips.map(trip=>Number(trip.id)):[...state.selected].map(Number);}
    function missingAttachmentTrip(){if(state.editingInvoiceId&&(state.editingInvoice?.legacy_attachments||[]).length)return null;return state.trips.find(trip=>requiredVoucherIds().includes(Number(trip.id))&&savedAttachments(trip).length+pendingAttachments(trip.id).length<1)||null;}
    function focusMissingAttachment(trip){billModal.classList.add('hidden');tripBody.querySelectorAll('tr').forEach(row=>row.classList.remove('missing-attachment'));const row=tripBody.querySelector(`[data-voucher-row="${trip.id}"]`);row?.classList.add('missing-attachment');row?.scrollIntoView({block:'center',inline:'nearest'});setTimeout(()=>row?.querySelector('[data-add-attachment]')?.focus(),20);window.AppToast?.(`Add at least one attachment for LR ${trip.lr_no||('SR '+trip.sr_no)}.`,'error',5500);}
    createBillBtn.addEventListener('click',openBill);document.getElementById('billClose').addEventListener('click',closeBill);document.getElementById('billCancel').addEventListener('click',closeBill);billModal.addEventListener('mousedown',e=>{if(e.target===billModal)closeBill();});totalInput.addEventListener('input',updateDraft);
    billForm.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();e.stopPropagation();closeBill();return;}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'){e.preventDefault();e.stopPropagation();billForm.requestSubmit();return;}if(e.key!=='Enter'||e.target===remarksInput)return;e.preventDefault();const order=[invoiceDate,totalInput,remarksInput,billSubmit],i=order.indexOf(e.target);if(e.target===invoiceDate&&!invoiceDate.value){invoiceDate.showPicker?.();return;}if(i>=0&&i<order.length-1){order[i+1].focus();order[i+1].select?.();}else if(e.target===billSubmit)billForm.requestSubmit();});
    billForm.addEventListener('submit',async e=>{e.preventDefault();const editing=!!state.editingInvoiceId,freight=Number(totalInput.value||0);if(freight<=0){window.AppToast?.('Enter Customer Freight.','error');totalInput.focus();return;}const missing=missingAttachmentTrip();if(missing){focusMissingAttachment(missing);return;}billSubmit.disabled=true;billSubmit.textContent=editing?'Saving...':'Creating...';const fd=new FormData();fd.append('invoice_date',invoiceDate.value);fd.append('customer_freight',totalInput.value);fd.append('remarks',remarksInput.value||'');const voucherIds=requiredVoucherIds();voucherIds.forEach(id=>pendingAttachments(id).forEach(item=>fd.append(`voucher_attachments[${id}][]`,item.file)));state.removedAttachmentIds.forEach(id=>fd.append('remove_voucher_attachment_ids[]',id));let url=routes.store;if(editing){url=`${routes.base}/${state.editingInvoiceId}`;fd.append('_method','PUT');}else{fd.append('customer_id',state.customerId);fd.append('sales_order_id',state.soId);voucherIds.forEach(id=>fd.append('voucher_ids[]',id));}
        try{const r=await fetch(url,{method:'POST',headers:{Accept:'application/json','X-CSRF-TOKEN':csrf},body:fd}),d=await responseData(r,'Unable to save the bill. Please try again.');if(!r.ok)throw new Error(r.status>=500?'Unable to save the bill. Please try again.':(Object.values(d.errors||{})[0]?.[0]||d.message||'Unable to save bill.'));const invoiceId=d.invoice.id;billModal.classList.add('hidden');state.selected.clear();if(editing){clearEdit();updateUrl();await loadData(false);}else{clearAttachmentDraft();await loadData(false);if(state.order&&Number(state.order.pending_count)===0){state.soId=null;state.order=null;soBtn.dataset.soId='';soBtn.textContent='Select SO';soBtn.classList.add('empty');updateUrl();await loadData(false);}}setStatus(d.message,'ok');window.AppToast?.(d.message||'Bill saved successfully.','success');openPrint(invoiceId,createBillBtn,true);}catch(err){window.AppToast?.(err.message||'Unable to save bill.','error',5500);}finally{billSubmit.disabled=false;billSubmit.innerHTML=state.editingInvoiceId?'Save Changes & Print <span class="kbd">Ctrl+S</span>':'Create Bill & Print <span class="kbd">Ctrl+S</span>';}});

    async function startEdit(id,opener){const inv=state.invoices.find(x=>Number(x.id)===Number(id));if(!inv)return;const previous={customerId:state.customerId,customerName:state.customerName,soId:state.soId,customerLabel:customerBtn.textContent,soLabel:soBtn.textContent};clearAttachmentDraft();state.editOpener=opener;state.editReturn=previous;state.editingInvoiceId=Number(id);state.customerId=Number(inv.customer_id);state.customerName=inv.customer_name||state.customerName;state.soId=Number(inv.sales_order_id);state.selected.clear();customerBtn.dataset.customerId=inv.customer_id;customerBtn.textContent=inv.customer_name||customerBtn.textContent;customerBtn.classList.remove('empty');soBtn.disabled=false;soBtn.dataset.soId=inv.sales_order_id;soBtn.textContent=inv.so_number||'SO';soBtn.classList.remove('empty');updateUrl();const loaded=await loadData(false);if(!loaded){const back=state.editReturn;clearEdit();state.customerId=back.customerId;state.customerName=back.customerName;state.soId=back.soId;customerBtn.dataset.customerId=back.customerId||'';customerBtn.textContent=back.customerLabel;customerBtn.classList.toggle('empty',!back.customerId);soBtn.disabled=!back.customerId;soBtn.dataset.soId=back.soId||'';soBtn.textContent=back.soLabel;soBtn.classList.toggle('empty',!back.soId);updateUrl();await loadData(false);setTimeout(()=>opener.focus(),20);return;}tripWrap.scrollTo({top:0,left:0,behavior:'smooth'});setTimeout(()=>createBillBtn.focus(),80);window.AppToast?.(`${inv.bill_no} loaded above. Review entries and choose Edit Bill.`, 'info', 5000);}
    async function cancelEdit(){const opener=state.editOpener,back=state.editReturn;clearEdit();if(back){state.customerId=back.customerId;state.customerName=back.customerName;state.soId=back.soId;customerBtn.dataset.customerId=back.customerId||'';customerBtn.textContent=back.customerLabel;customerBtn.classList.toggle('empty',!back.customerId);soBtn.disabled=!back.customerId;soBtn.dataset.soId=back.soId||'';soBtn.textContent=back.soLabel;soBtn.classList.toggle('empty',!back.soId);}updateUrl();await loadData(false);setTimeout(()=>opener?.isConnected?opener.focus():focusFirstPending(),20);}
    cancelEditBtn.addEventListener('click',cancelEdit);
    invoiceBody.addEventListener('click',e=>{const ed=e.target.closest('[data-edit-invoice]');if(ed){startEdit(Number(ed.dataset.editInvoice),ed);return;}const pr=e.target.closest('[data-print-invoice]');if(pr)openPrint(Number(pr.dataset.printInvoice),pr,true);});
    invoiceBody.addEventListener('keydown',e=>{const ed=e.target.closest('[data-edit-invoice]');if(ed&&e.key==='Enter'){e.preventDefault();startEdit(Number(ed.dataset.editInvoice),ed);return;}const pr=e.target.closest('[data-print-invoice]');if(pr&&e.key==='Enter'){e.preventDefault();openPrint(Number(pr.dataset.printInvoice),pr,true);}});

    const printModal=document.getElementById('printModal'),printFrame=document.getElementById('printFrame');let autoPrint=false;
    function openPrint(id,opener,auto=false){state.printOpener=opener;autoPrint=auto;printFrame.src=`${routes.base}/${id}/print?embedded=1`;printModal.classList.remove('hidden');}
    function closePrint(){printModal.classList.add('hidden');printFrame.src='about:blank';autoPrint=false;setTimeout(()=>state.printOpener?.focus?.(),0);}
    printFrame.addEventListener('load',()=>{if(printFrame.src!=='about:blank'){try{printFrame.contentDocument?.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();closePrint();}});}catch(e){}if(autoPrint){setTimeout(()=>{try{printFrame.contentWindow.focus();printFrame.contentWindow.print();}catch(e){}},250);autoPrint=false;}}});
    document.getElementById('printNow').addEventListener('click',()=>{try{printFrame.contentWindow.focus();printFrame.contentWindow.print();}catch(e){}});document.getElementById('printClose').addEventListener('click',closePrint);printModal.addEventListener('mousedown',e=>{if(e.target===printModal)closePrint();});
    window.addEventListener('message',e=>{if(e.origin===window.location.origin&&e.data?.type==='xyz-invoice-afterprint'&&!printModal.classList.contains('hidden'))closePrint();});

    document.getElementById('closeBilling').addEventListener('click',()=>window.AppPageExit?.('#nav-sale'));
    window.addEventListener('keydown',e=>{if(!printModal.classList.contains('hidden')){if(e.key==='Escape'){e.preventDefault();e.stopImmediatePropagation();closePrint();}return;}if(!billModal.classList.contains('hidden')){if(e.key==='Escape'){e.preventDefault();e.stopImmediatePropagation();closeBill();}return;}if(e.altKey&&e.key.toLowerCase()==='a'){e.preventDefault();toggleAll();return;}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='b'){e.preventDefault();openBill();return;}});

    syncButtons();loadData(false).then(()=>{if(shortcutSelectionApplied)return;if(!state.customerId)setTimeout(()=>customerBtn.focus(),30);else if(!state.soId&&!state.editingInvoiceId)setTimeout(()=>soBtn.focus(),30);else if(!state.editingInvoiceId)setTimeout(()=>focusFirstPending(),30);});
});
</script>
@endpush
